import{z as s,x as o,o as e,c as m,q as n,j as B,D as E,d as t,s as A,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"宏观 regime 的识别","description":"","frontmatter":{"title":"宏观 regime 的识别","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-regime-identification.md","filePath":"quant/mac-regime-identification.md","lastUpdated":1791063341000}'),d={name:"quant/mac-regime-identification.md"};function p(c,a,h,u,_,f){const r=o("Mermaid");return e(),m("div",null,[a[2]||(a[2]=n('<h1 id="宏观-regime-的识别" tabindex="-1">宏观 regime 的识别 <a class="header-anchor" href="#宏观-regime-的识别" aria-label="Permalink to &quot;宏观 regime 的识别&quot;">​</a></h1><div class="epigraph"><p>宏观策略的第一决定不是买什么，而是承认现在处于哪种状态；状态命名错了，后面每一步都错得整齐。</p><footer>—— 据 Hamilton, Econometrica, 1989 与 Burns &amp; Mitchell, Measuring Business Cycles, 1946 整理</footer></div><p><a href="/quant/ap-map">上一课</a>把账户绩效收在测量纪律上：先钉测量再谈评价，核算保忠实、评估保公平——树序的下一课程转向宏观与跨资产，视角从账户换到资产。资产这一侧，<a href="/quant/cta-tsmom">时间序列动量 CTA</a>对宏观状态是被动的：趋势自己会翻仓；主动宏观策略要先回答：现在处于哪种状态，这个判断有多可信。本课是「宏观与跨资产策略」的第一课。后面的象限、流动性、战术配置与各资产表达，都默认你会把状态写成概率而不是叙事。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跨资产的相关结构、风险溢价、对冲工具的有效性都随宏观状态变：<a href="/quant/macro-factor-set">宏观因子</a>把跨资产共同收益命名为增长、通胀、流动性三类冲击；<a href="/quant/time-varying-rp">风险溢价时变</a>说明条件溢价 \\(\\lambda_t\\) 随状态移动。缺口因此不是「讲宏观故事」，而是把状态变成可操作、可证伪、能逐点复现的对象：当前状态是什么？转移概率多大？识别滞后几期？留在叙事层的仓位映射全凭口径——「滞胀要来了」无法回测，也无法归因。</p><p><span class="marginnote">「regime（区制）」翻译成白话：市场处在哪一档「天气」——扩张、衰退、高波动等。马尔可夫切换模型做的事，就是让数据自己在「晴天模式」与「雨天模式」之间切换，并每天给出「今天是雨天的概率」这样的读数。</span></p><h3 id="三条识别路径的分工" tabindex="-1">三条识别路径的分工 <a class="header-anchor" href="#三条识别路径的分工" aria-label="Permalink to &quot;三条识别路径的分工&quot;">​</a></h3><p>规则法用公布口径的指标与阈值：NBER 峰谷认定是事后裁定，实时版本必须换成月度代理——失业率低点、产出持续收缩、信用利差过阈值。统计法由 Hamilton 把增长序列写成两区制的马尔可夫切换：扩张均值高、衰退均值低，滤波递归输出 \\(\\Pr(s_t=j\\mid\\mathcal{F}_t)\\)。资产内生法把价格本身当状态的充分统计量：信用利差、期限斜率、美元与波动率日频可得，但已含溢价变动。三条路分工：规则法与官方口径对表，统计法负责估计，价格代理负责实时。</p><p><span class="marginnote">滤波概率只用 \\(t\\) 期及以前的信息；平滑概率 \\(\\Pr(s_t=j\\mid\\mathcal{F}_T)\\) 用了全样本。回测与实盘只能用滤波口径——把平滑概率画进仓位图，等于把下一次衰退的确认偷进拐点前的仓位，夏普凭空多一截。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>统计法落地按三步：状态数 \\(K\\) 先取 2，不为拟合某段行情加态；转移矩阵 \\(p_{ij}=\\Pr(s_t=j\\mid s_{t-1}=i)\\) 与各区制均值方差由 Hamilton 滤波的极大似然一起估出；输出当前概率、转移概率与区制参数。验收看三条：滤波概率对已认定衰退期的覆盖与迟滞（以月计）、转移概率在滚动窗口的稳定性、对切换的响应速度。资产内生法先把指标标准化，再用阈值或切换模型收敛成概率。两路不互斥：宏观数据月频且事后修正，价格代理日频且实时，实战用价格概率日度监控、宏观滤波月度校准，两套概率背离即是信号。</p>',11)),(e(),B(l,null,{default:E(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%9C%88%E5%BA%A6%E5%AE%8F%E8%A7%82%E5%BA%8F%E5%88%97%22%5D%20--%3E%20F%5B%22%E5%8C%BA%E5%88%B6%E8%BD%AC%E7%A7%BB%E6%BB%A4%E6%B3%A2%22%5D%0A%20%20P%5B%22%E6%97%A5%E9%A2%91%E4%BB%B7%E6%A0%BC%E4%BB%A3%E7%90%86%22%5D%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E6%88%96%E5%88%87%E6%8D%A2%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20F%20--%3E%20PR%5B%22%E7%8A%B6%E6%80%81%E6%A6%82%E7%8E%87%EF%BC%88%E6%BB%A4%E6%B3%A2%E5%8F%A3%E5%BE%84%EF%BC%89%22%5D%0A%20%20TH%20--%3E%20PR%0A%20%20PR%20--%3E%20W%5B%22%E4%BB%93%E4%BD%8D%E6%98%A0%E5%B0%84%EF%BC%88%E5%90%8E%E8%AF%BE%EF%BC%89%22%5D%0A%20%20PR%20--%3E%20MON%5B%22%E8%BF%9F%E6%BB%9E%E4%B8%8E%E8%AF%AF%E6%8A%A5%E7%9B%91%E6%8E%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"状态要写成概率而不是分类：转移概率给出置信度与持续性，\\(p_{11}\\) 高意味着状态大概率延续，风险预算按期望状态久期分配；点估计式的全进全出在概率贴着 0.5 抖动时高频翻仓，把识别噪声直接变成交易成本。误判成本不对称：把衰退当成扩张，会在下跌里持续承接暴露；反向误判只损失机会成本。阈值因此不应居中——宁可多付误报成本，也要压缩下行漏报。相关性随状态变是另一半：危机里跨资产相关性抬升使名义分散失效，状态概率因此同时是收益输入与风险开关；后者由流动性条件一课接手。",-1)),(e(),B(l,null,{default:E(()=>[A(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E6%BB%A4%E6%B3%A2%E7%8A%B6%E6%80%81%E6%A6%82%E7%8E%87%22%5D%20--%3E%20P11%5B%22%E8%BD%AC%E7%A7%BB%E6%A6%82%E7%8E%87%20p11%20%E9%AB%98%22%5D%0A%20%20P11%20--%3E%20DU%5B%22%E6%9C%9F%E6%9C%9B%E7%8A%B6%E6%80%81%E4%B9%85%E6%9C%9F%E9%95%BF%22%5D%0A%20%20DU%20--%3E%20RB%5B%22%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E6%8C%89%E4%B9%85%E6%9C%9F%E5%88%86%E9%85%8D%22%5D%0A%20%20PR%20--%3E%20B5%5B%22%E6%A6%82%E7%8E%87%E8%B4%B4%E7%9D%80%200.5%20%E6%8A%96%E5%8A%A8%22%5D%0A%20%20B5%20--%3E%20PB%5B%22%E6%8C%89%E6%A6%82%E7%8E%87%E5%B8%A6%E6%B8%90%E8%BF%9B%E8%B0%83%E4%BB%93%22%5D%0A%20%20B5%20--%3E%20AO%5B%22%E7%A6%81%E6%AD%A2%E5%85%A8%E8%BF%9B%E5%85%A8%E5%87%BA%22%5D%0A%20%20MIS%5B%22%E8%AF%AF%E5%88%A4%E6%88%90%E6%9C%AC%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E5%81%8F%E5%90%91%E5%AE%81%E5%8F%AF%E8%AF%AF%E6%8A%A5%E8%A1%B0%E9%80%80%22%5D%0A%20%20TH%20--%3E%20RB%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字感受转移概率：若扩张态的 \\(p_{11}=0.97\\)，下月仍扩张的概率是 97%，期望持续约 \\(1/(1-0.97)\\approx 33\\) 个月；若掉到 0.90，期望持续只剩 10 个月。风险预算能拿多久，直接由这个数决定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>regime 是后验命名：峰谷认定滞后数月才公布，实时识别必带误报与迟报，滤波能压缩不能消除。状态数与持续期参数的样本内最优是过拟合温床，\\(K\\) 从 2 升到 3 常只为迁就一段特殊时期；换窗口重估后状态边界移动，映射规则要随参数版本化。宏观数据修正使「同一季度」在不同 vintage 下属于不同状态，回测不用首次公布值就会系统性好看（收束课专讲）。也不承诺拐点择时：确认状态比预测转折容易得多，仓位映射按概率带渐进调仓，不押单点。叙事命名只做沟通用，不进自动规则。</p><p><span class="marginnote">常见误区：以为模型能「预测拐点」。它压缩迟滞，不消除迟滞：官方峰谷认定滞后数月才公布，滤波概率最早也只是「更快地怀疑」。正确用法是按概率渐进调仓，而不是等一个「转折日」押注。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>识别的对象是状态的概率与转移，不是叙事；叙事不可证伪，无法回测归因。</li><li>规则法、区制转移、资产内生代理三条路分工：与官方口径对表、统计估计、实时监控。</li><li>回测与实盘只能用滤波或预测口径；平滑概率把未来状态偷进拐点前的仓位。</li><li>误判成本不对称，阈值应向「宁可误报」倾斜；识别同时是收益输入与风险开关。</li><li>出处：Hamilton, Econometrica, 1989；Burns &amp; Mitchell, Measuring Business Cycles, 1946；冲击命名与溢价时变见<a href="/quant/macro-factor-set">宏观因子</a>与<a href="/quant/time-varying-rp">风险溢价时变</a>。</li></ul>',6))])}const C=s(d,[["render",p]]);export{F as __pageData,C as default};
